property_remove.validation:
removalSchema = z.object({
  propertyId: z.string().regex(/^[A-Za-z0-9_-]{1,150}$/),
  reason: z.enum(['not_interesting', 'collaboration_ended', 'sold']),
  soldDisposition: z.enum(['agency', 'other_agency', 'owner']).optional(),
  soldPrice: z.number().finite().positive().max(1e12).optional(),
  agentMessage: z.string().trim().max(4000),
}).strict().superRefine((value, ctx) => {
  if (value.reason === 'sold' && (!value.soldDisposition || !value.soldPrice)) {
    ctx.addIssue({ code: z.ZodIssueCode.custom, message: 'Completează prețul și autorul vânzării.' });
  }
})

sale_setup.validation:
saleParticipantSchema = z.object({ id, role: z.enum(['buyer', 'owner', 'notary', 'collaborator']), contactId: id.nullable().optional(), name: z.string().trim().max(200), email: z.string().trim().email().or(z.literal('')), phone: z.string().trim().max(50).nullable().optional(), preferredChannel: z.enum(['email', 'phone', 'whatsapp']).optional() }).strip()

saleChecklistSetupSchema = z.object({ id, label: z.string().trim().min(1).max(240), participantRole: z.enum(['buyer', 'owner']), participantId: id.nullable().optional(), scope: z.enum(['property', 'participant', 'transaction']).optional(), stage: z.enum(['reservation', 'precontract', 'contract']).optional(), appliesToStages: z.array(z.enum(['reservation', 'precontract', 'contract'])).max(3).optional(), status: z.enum(['required', 'requested', 'received_needs_review', 'verified', 'rejected', 'expired', 'not_required']), required: z.boolean(), notes: z.string().max(1000).nullable().optional(), notRequiredReason: z.string().max(1000).nullable().optional() }).strip()

saleSetupSchema = z.object({ participants: z.array(saleParticipantSchema).min(2).max(20), agreedPrice: z.number().positive().max(1e9).nullable(), reservationAmount: z.number().nonnegative().max(1e9).nullable().optional().default(null), precontractAmount: z.number().nonnegative().max(1e9).nullable().optional().default(null), financingType: z.enum(['cash', 'credit', 'unknown']), checklist: z.array(saleChecklistSetupSchema).max(100), notary: z.object({ name: z.string().trim().max(200).nullable().optional(), email: z.string().trim().email().or(z.literal('')).nullable().optional(), phone: z.string().trim().max(50).nullable().optional(), address: z.string().trim().max(400).nullable().optional(), appointmentAt: z.string().datetime().nullable().optional() }).strip().nullable(), nextAction: z.string().trim().max(2000).nullable().optional(), nextActionAt: z.string().datetime({ offset: true }).nullable().optional(), expectedUpdatedAt: z.string().datetime({ offset: true }).nullable().optional() }).strict().superRefine((input, ctx) => {
  if (input.agreedPrice != null && (input.reservationAmount ?? 0) + (input.precontractAmount ?? 0) > input.agreedPrice) ctx.addIssue({ code: 'custom', path: ['precontractAmount'], message: 'Rezervarea și antecontractul nu pot depăși prețul de vânzare.' });
  for (const field of ['participants', 'checklist'] as const) if (new Set(input[field].map(row => row.id)).size !== input[field].length) ctx.addIssue({ code: 'custom', path: [field], message: 'Identificatorii trebuie să fie unici.' });
})

